<p><a href="/student">← My sections</a></p><p class="text-muted"><?= e($s['course_code'].' · '.$s['course_title']) ?></p><h2 class="h5 mt-4">Materials</h2><div class="list-group"><?php foreach($materials as $m): ?><div class="list-group-item"><a href="/student/materials/<?= (int)$m['id'] ?>/download"><?= e($m['title']) ?></a><p class="small text-muted mb-0"><?= e($m['description']) ?></p></div><?php endforeach ?></div><h2 class="h5 mt-4">Assignments</h2><div class="row g-3"><?php foreach($assignments as $a): ?><div class="col-lg-6"><div class="card"><div class="card-body"><h3 class="h6"><?= e($a['title']) ?></h3><p class="small text-muted">Due: <?= e($a['due_at']??'No deadline') ?></p><p><?= nl2br(e($a['instructions'])) ?></p><?php if($a['submission_id']): ?><div class="alert alert-success">Final submission received <?= e($a['submitted_at']) ?>. <a href="/student/submissions/<?= (int)$a['submission_id'] ?>/download">Download your file</a></div><?php if($a['status']==='released'): ?><p><strong>Grade:</strong> <?= e((string)$a['score']) ?> / 100</p><p><strong>Feedback:</strong> <?= nl2br(e($a['feedback'])) ?></p><?php else: ?><p class="text-muted">Grade and feedback not released yet.</p><?php endif ?><?php elseif($a['due_at'] && strtotime($a['due_at']) < time()): ?><p class="text-danger">Submission deadline has passed.</p><?php else: ?><form method="post" action="/student/submissions" enctype="multipart/form-data"><input type="hidden" name="_csrf" value="<?= csrf() ?>"><input type="hidden" name="assignment_id" value="<?= (int)$a['id'] ?>"><label class="form-label">Final submission (cannot replace)</label><input type="file" name="file" class="form-control mb-2" required><button class="btn btn-primary" onclick="return confirm('Submit this file as your one final submission?')">Submit final work</button></form><?php endif ?></div></div></div><?php endforeach ?></div><?php if(!$assignments): ?><p>No assignments yet.</p><?php endif ?>
